<div class="top"><h1>Messages du formulaire de contact</h1></div>
<?php foreach ($rows as $m): ?><div class="card"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><div><b><?= e($m['name']) ?></b> <?= $m['status'] === 'new' ? '<span class="badge b-warn">Nouveau</span>' : '<span class="badge b-ok">Traité</span>' ?><br><small class="muted"><?= fdate($m['created_at'], true) ?> · <?= e($m['phone']) ?> · <?= e($m['email']) ?></small></div><div style="display:flex;gap:8px"><?php if ($m['phone']): ?><a class="btn btn-g btn-sm" target="_blank" rel="noopener" href="<?= e('https://wa.me/' . preg_replace('/\D/', '', $m['phone']) . '?text=' . rawurlencode('Bonjour ' . $m['name'] . ', ')) ?>"><?= ic('wa') ?> WhatsApp</a><?php endif; ?><?php if ($m['status'] === 'new'): ?><form method="post" action="/admin/messages/<?= (int) $m['id'] ?>/traite"><?= csrf_field() ?><button class="btn btn-p btn-sm">Marquer traité</button></form><?php endif; ?></div></div><p style="margin:12px 0 0"><?= nl2br(e($m['message'])) ?></p></div><?php endforeach; ?><?php if (!$rows): ?><div class="card muted">Aucun message.</div><?php endif; ?>
